/*
 * A008240  Coordination sequence T3 for Zeolite Code THO.
 * https://oeis.org/A008240
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) is generated by the rational function
 *            (1+2*x+2*x^2+7*x^3+6*x^4+6*x^5+2*x^6+14*x^7-x^8+10*x^9-2*x^10+5*x^11-8*x^12+4*x^13)
 *            / ((1-x)^3*(1+x^2)*(1+x+x^2)*(1+x^4)). For n ≥ 24 the sequence
 *            satisfies the linear recurrence a(n) = 2*a(n-1) – 2*a(n-2) +
 *            3*a(n-3) – 4*a(n-4) + 4*a(n-5) – 4*a(n-6) + 4*...
 * Range:     u8 n <= 11, u16 n <= 181, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>

static const seq_t base_terms[24] = {
    1,    4,    8,   18,   34,   50,   68,  100,
  130,  160,  204,  246,  286,  338,  392,  448,
  514,  580,  648,  726,  802,  878,  968, 1060
};

seq_t a(idx_t n)
{
    /* Cache the first terms and grow the cache as needed. */
    static seq_t *cache = NULL;
    static idx_t cache_len = 0;

    if (cache == NULL) {
        cache_len = 24;
        cache = (seq_t *)malloc(cache_len * sizeof(seq_t));
        for (idx_t i = 0; i < 24; ++i)
            cache[i] = base_terms[i];
    }
    if (n < cache_len)
        return cache[n];

    /* Extend the cache to contain the requested term. */
    idx_t new_len = n + 1;
    if (new_len > cache_len) {
        cache = (seq_t *)realloc(cache, new_len * sizeof(seq_t));
        for (idx_t i = cache_len; i < new_len; ++i) {
            if (i < 24) {            /* already initialized */
                cache[i] = base_terms[i];
            } else {                 /* recurrence for i ≥ 24 */
                seq_t pos = 2 * cache[i - 1] + 3 * cache[i - 3] +
                            4 * cache[i - 5] + 4 * cache[i - 7] +
                            2 * cache[i - 9] + cache[i - 11];
                seq_t neg = 2 * cache[i - 2] + 4 * cache[i - 4] +
                            4 * cache[i - 6] + 3 * cache[i - 8] +
                            2 * cache[i - 10];
                cache[i] = pos - neg;
            }
        }
        cache_len = new_len;
    }
    return cache[n];
}
